import { OWLManager } from 'file:///${OWLAPI_SOURCE}/apibinding/index.js';
import { IRI, OWLOntologyLoaderConfiguration as LC, OWLOntologyWriterConfiguration as WC, AddAxiom, RemoveAxiom, SetOntologyID } from 'file:///${OWLAPI_SOURCE}/model/index.js';
import { StringDocumentSource, StringDocumentTarget } from 'file:///${OWLAPI_SOURCE}/io/index.js';
import { OWLDocumentFormats as F } from 'file:///${OWLAPI_SOURCE}/formats/index.js';
import { OWLObjectDuplicator } from 'file:///${OWLAPI_SOURCE}/util/index.js';
import { ManchesterOWLSyntaxOWLObjectRendererImpl } from 'file:///${OWLAPI_SOURCE}/manchestersyntax/renderer/index.js';
import { OWL2DLProfile } from 'file:///${OWLAPI_SOURCE}/profiles/index.js';
const out = [];
const shape = e => ({ name:e.name, code:e.code, resource:e.resource, limit:e.limit, message:e.message, cause:e.cause ? shape(e.cause) : undefined });
async function probe(id, fn) { try {out.push({id, outcome:'returned', result:await fn()});} catch(e) {out.push({id, outcome:'threw', error:shape(e)});} }
const m = OWLManager.createOWLOntologyManager(), df=m.getOWLDataFactory();
const makeOntology = id => m.createOntology(df.getOWLOntologyID(IRI.create(`urn:research:${id}`)));
await probe('loader-defaults', () => ({...new LC()}));
for (const value of [null, Infinity, -1, 0]) await probe(`loader-timeout-${value}`, () => new LC({timeoutMs:value}).timeoutMs);
await probe('loader-java-methods', () => ['setConnectionTimeout','getConnectionTimeout','setRetriesToAttempt','setFollowRedirects','setEntityExpansionLimit','setStrict'].map(key => [key,typeof new LC()[key]]));
await probe('writer-noop-identity', () => {const c=new WC(); return c === c.withIndentSize(4);});
await probe('writer-chain', () => {const c=new WC().withIndentSize(2).withBannersEnabled(false).withIndenting(false); return {indent:c.getIndentSize(), banners:c.shouldUseBanners()};});
await probe('writer-negative-indent', () => new WC().withIndentSize(-1).getIndentSize());
const p=df.getOWLAnnotationProperty(IRI.create('urn:research:p')), a=df.getOWLClass(IRI.create('urn:research:A'));
let annotation=df.getOWLAnnotation(p, df.getOWLLiteral('x'));
for(let n=1;n<65;n++) annotation=df.getOWLAnnotation(p,df.getOWLLiteral('x'),[annotation]);
const ax=df.getOWLDeclarationAxiom(a,[annotation]), nested=makeOntology('nested');
await probe('annotation65-direct-add', () => m.addAxiom(nested,ax));
await probe('annotation65-add-record', () => !!new AddAxiom(nested,ax));
await probe('annotation65-remove', () => m.removeAxiom(nested,ax));
await probe('annotation65-duplicate', () => !!new OWLObjectDuplicator(m).duplicateObject(ax));
await probe('annotation65-manchester', () => new ManchesterOWLSyntaxOWLObjectRendererImpl().render(ax).length);
const large=makeOntology('large'), longLiteral=df.getOWLLiteral('x'.repeat(1048577));
m.addAxioms(large,[df.getOWLDeclarationAxiom(a),df.getOWLDeclarationAxiom(p),df.getOWLAnnotationAssertionAxiom(p,a.iri,longLiteral)]);
await probe('literal1048577-profile', async () => {const r=await new OWL2DLProfile().checkOntology(large); return {inProfile:r.isInProfile(),status:r.status,violations:r.getViolations(),unverified:r.unverifiedChecks};});
for(const [id,format] of [['functional',F.FUNCTIONAL],['turtle',F.TURTLE],['rdfxml',F.RDF_XML],['owlxml',F.OWL_XML]]) {
 const target=new StringDocumentTarget();
 await probe(`literal1048577-save-${id}`,async()=>{await m.saveOntology(large,format,target); return {bytes:new TextEncoder().encode(target.toString()).length};});
 out.push({id:`literal1048577-target-after-${id}`,bytes:new TextEncoder().encode(target.toString()).length});
}
const netzero=makeOntology('netzero'), basic=df.getOWLDeclarationAxiom(a);
await probe('batch-netzero', () => ({result:m.applyChanges([new AddAxiom(netzero,basic),new RemoveAxiom(netzero,basic)]),count:netzero.getAxiomCount()}));
const batch=makeOntology('batch'), clash=makeOntology('clash');
await probe('batch-collision', () => m.applyChanges([new AddAxiom(batch,basic),new SetOntologyID(batch,clash.getOntologyID())]));
out.push({id:'batch-count-after-collision',count:batch.getAxiomCount()});
const filtered=await m.loadOntologyFromOntologyDocument(new StringDocumentSource('Ontology(<urn:research:filtered>)',{format:F.FUNCTIONAL}),new LC({loadAnnotationAxioms:false}));
await probe('annotation-disabled-later-add', () => ({result:m.addAxiom(filtered,df.getOWLAnnotationAssertionAxiom(p,a.iri,df.getOWLLiteral('x'))),count:filtered.getAxiomCount()}));
await probe('save-reused-target',async()=>{const t=new StringDocumentTarget(); await m.saveOntology(netzero,F.FUNCTIONAL,t);const first=t.toString();await m.saveOntology(netzero,F.FUNCTIONAL,t);return {firstLength:first.length,secondLength:t.toString().length,equal:t.toString()===first};});
await probe('profile-empty-work-zero',async()=>{const r=await new OWL2DLProfile().checkOntology(netzero,{maxWork:0});return {inProfile:r.isInProfile(),status:r.status,unverified:r.unverifiedChecks};});
console.log(JSON.stringify({runtime:process.version,results:out},null,2));

