import java.util.*;
import java.util.stream.*;
import org.semanticweb.owlapi.apibinding.OWLManager;
import org.semanticweb.owlapi.model.*;
import org.semanticweb.owlapi.io.*;
import org.semanticweb.owlapi.formats.*;
import org.semanticweb.owlapi.profiles.*;
import org.semanticweb.owlapi.util.*;
import org.semanticweb.owlapi.manchestersyntax.renderer.ManchesterOWLSyntaxOWLObjectRendererImpl;

class ProbeJava {
 interface Run {Object run() throws Exception;}
 static void probe(String name,Run fn) {try {System.out.println(name+"\tRETURN\t"+fn.run());}catch(Throwable e){System.out.println(name+"\tTHROW\t"+e.getClass().getName()+": "+e.getMessage());}}
 public static void main(String[] args) throws Exception {
  System.out.println("runtime\t"+System.getProperty("java.runtime.version"));
  System.out.println("owlapi-origin\t"+OWLManager.class.getProtectionDomain().getCodeSource().getLocation());
  System.out.println("api-origin\t"+OWLOntologyLoaderConfiguration.class.getProtectionDomain().getCodeSource().getLocation());
  OWLOntologyLoaderConfiguration lc=new OWLOntologyLoaderConfiguration();
  probe("loader-defaults",()->"connection="+lc.getConnectionTimeout()+", retries="+lc.getRetriesToAttempt()+", followRedirects="+lc.isFollowRedirects()+", strict="+lc.isStrict()+", entityExpansion="+lc.getEntityExpansionLimit());
  probe("connection-negative-set",()->lc.setConnectionTimeout(-1).getConnectionTimeout());
  probe("retry-negative-set",()->lc.setRetriesToAttempt(-1).getRetriesToAttempt());
  String prefix="org.semanticweb.owlapi.model.parameters.ConfigurationOptions.";
  System.setProperty(prefix+"CONNECTION_TIMEOUT","123");
  probe("system-property-existing-config",()->lc.getConnectionTimeout());
  probe("system-property-instance-override",()->lc.setConnectionTimeout(456).getConnectionTimeout());
  System.clearProperty(prefix+"CONNECTION_TIMEOUT");
  var sax=SAXParsers.initParserWithOWLAPIStandards(null,lc.getEntityExpansionLimit());
  System.out.println("sax-class\t"+sax.getClass().getName());
  for(String prop:List.of("entityExpansionLimit","maxElementDepth","totalEntitySizeLimit","maxGeneralEntitySizeLimit","maxParameterEntitySizeLimit","entityReplacementLimit","maxXMLNameLimit","elementAttributeLimit")) probe("sax-"+prop,()->sax.getProperty("http://www.oracle.com/xml/jaxp/properties/"+prop));
  probe("entity-limit-zero",()->SAXParsers.initParserWithOWLAPIStandards(null,"0").getProperty("http://www.oracle.com/xml/jaxp/properties/entityExpansionLimit"));
  probe("writer-noop-identity",()->{var c=new OWLOntologyWriterConfiguration();return c==c.withIndentSize(4);});
  probe("writer-chain",()->{var c=new OWLOntologyWriterConfiguration().withIndentSize(2).withBannersEnabled(false).withIndenting(false);return "indent="+c.getIndentSize()+", banners="+c.shouldUseBanners();});
  probe("writer-negative-indent",()->new OWLOntologyWriterConfiguration().withIndentSize(-1).getIndentSize());
  var m=OWLManager.createOWLOntologyManager();var df=m.getOWLDataFactory();
  var p=df.getOWLAnnotationProperty(IRI.create("urn:research:p"));var a=df.getOWLClass(IRI.create("urn:research:A"));
  OWLAnnotation annotation=df.getOWLAnnotation(p,df.getOWLLiteral("x"));
  for(int n=1;n<65;n++) annotation=df.getOWLAnnotation(p,df.getOWLLiteral("x"),List.of(annotation));
  var ax=df.getOWLDeclarationAxiom(a,List.of(annotation));var nested=m.createOntology(IRI.create("urn:research:nested"));
  probe("annotation65-direct-add",()->m.addAxiom(nested,ax));
  probe("annotation65-add-record",()->new AddAxiom(nested,ax)!=null);
  probe("annotation65-remove",()->m.removeAxiom(nested,ax));
  probe("annotation65-duplicate",()->new OWLObjectDuplicator(m).duplicateObject(ax)!=null);
  probe("annotation65-manchester",()->new ManchesterOWLSyntaxOWLObjectRendererImpl().render(ax).length());
  var large=m.createOntology(IRI.create("urn:research:large"));
  var literal=df.getOWLLiteral("x".repeat(1048577));
  m.addAxioms(large,Stream.of(df.getOWLDeclarationAxiom(a),df.getOWLDeclarationAxiom(p),df.getOWLAnnotationAssertionAxiom(p,a.getIRI(),literal)));
  probe("literal1048577-profile",()->{var r=new OWL2DLProfile().checkOntology(large);return "inProfile="+r.isInProfile()+", violations="+r.getViolations().size();});
  Map<String,OWLDocumentFormat> formats=new LinkedHashMap<>();formats.put("functional",new FunctionalSyntaxDocumentFormat());formats.put("turtle",new TurtleDocumentFormat());formats.put("rdfxml",new RDFXMLDocumentFormat());formats.put("owlxml",new OWLXMLDocumentFormat());
  for(var entry:formats.entrySet()){var target=new StringDocumentTarget();probe("literal1048577-save-"+entry.getKey(),()->{m.saveOntology(large,entry.getValue(),target);return "chars="+target.toString().length();});}
  var netzero=m.createOntology(IRI.create("urn:research:netzero"));var basic=df.getOWLDeclarationAxiom(a);
  probe("batch-netzero",()->"result="+m.applyChanges(List.of(new AddAxiom(netzero,basic),new RemoveAxiom(netzero,basic)))+", count="+netzero.getAxiomCount());
  var batch=m.createOntology(IRI.create("urn:research:batch"));var clash=m.createOntology(IRI.create("urn:research:clash"));
  probe("batch-collision",()->m.applyChanges(List.of(new AddAxiom(batch,basic),new SetOntologyID(batch,clash.getOntologyID()))));
  System.out.println("batch-count-after-collision\t"+batch.getAxiomCount());
  var filtered=m.loadOntologyFromOntologyDocument(new StringDocumentSource("Ontology(<urn:research:filtered>)",IRI.create("urn:research:filtered-document"),new FunctionalSyntaxDocumentFormat(),null),lc.setLoadAnnotationAxioms(false));
  probe("annotation-disabled-later-add",()->"result="+m.addAxiom(filtered,df.getOWLAnnotationAssertionAxiom(p,a.getIRI(),df.getOWLLiteral("x")))+", count="+filtered.getAxiomCount());
  probe("save-reused-target",()->{var t=new StringDocumentTarget();m.saveOntology(netzero,new FunctionalSyntaxDocumentFormat(),t);String first=t.toString();m.saveOntology(netzero,new FunctionalSyntaxDocumentFormat(),t);return "firstLength="+first.length()+", secondLength="+t.toString().length()+", equal="+first.equals(t.toString());});
 }
}

import { OWLManager } from 'file:///${OWLAPI_SOURCE}/apibinding/index.js';
import { OWLOntologyLoaderConfiguration as LC, IRI } from 'file:///${OWLAPI_SOURCE}/model/index.js';
import { StringDocumentSource } from 'file:///${OWLAPI_SOURCE}/io/index.js';
import { OWLDocumentFormats as F } from 'file:///${OWLAPI_SOURCE}/formats/index.js';
const results=[];
const shape=e=>({name:e.name,code:e.code,resource:e.resource,limit:e.limit,message:e.message,cause:e.cause?shape(e.cause):undefined});
async function probe(id,fn){try{results.push({id,outcome:'returned',result:await fn()});}catch(e){results.push({id,outcome:'threw',error:shape(e)});}}
const load=(text,format,configuration)=>OWLManager.createOWLOntologyManager().loadOntologyFromOntologyDocument(new StringDocumentSource(text,format?{format}:{}),configuration).then(o=>o.getAxiomCount());
await probe('sniff-leading9000-spaces',()=>load(' '.repeat(9000)+'Ontology(<urn:research:sniff>)'));
await probe('sniff-leading9000-spaces-explicit',()=>load(' '.repeat(9000)+'Ontology(<urn:research:sniff>)',F.FUNCTIONAL));
await probe('xml-unused-external-entity',()=>load('<!DOCTYPE Ontology [<!ENTITY unused SYSTEM "https://example.invalid/no-network">]><Ontology xmlns="http://www.w3.org/2002/07/owl#" ontologyIRI="urn:research:xml"/>',F.OWL_XML));
const nested='<Ontology xmlns="http://www.w3.org/2002/07/owl#" ontologyIRI="urn:research:deepxml"><Declaration><Class IRI="urn:research:A"/></Declaration><SubClassOf><Class IRI="urn:research:A"/>'+'<ObjectComplementOf>'.repeat(110)+'<Class IRI="urn:research:A"/>'+'</ObjectComplementOf>'.repeat(110)+'</SubClassOf></Ontology>';
await probe('xml-complement-depth110',()=>load(nested,F.OWL_XML));
await probe('functional-literal1048577',()=>load('Ontology(<urn:research:literal> Annotation(<urn:research:p> "'+'x'.repeat(1048577)+'"))',F.FUNCTIONAL));
const trig='@prefix owl: <http://www.w3.org/2002/07/owl#> . <urn:g1> { <urn:A> a owl:Class . } <urn:g2> { <urn:B> a owl:Class . }';
await probe('trig-two-named-graphs',()=>load(trig,F.TRIG));
const turtle='@prefix owl: <http://www.w3.org/2002/07/owl#> . <urn:o> a owl:Ontology . <urn:x> <urn:p> "value" .';
await probe('turtle-undeclared-annotation-default',()=>load(turtle,F.TURTLE));
await probe('turtle-undeclared-annotation-compatible',()=>load(turtle,F.TURTLE,new LC({parsingMode:'compatible'})));
for(const hostname of ['context.example','fcorp.example']){
 let calls=0;
 const m=OWLManager.createOWLOntologyManager({documentLoader:{load:async()=>{calls++;return '{"@context":{"x":"urn:x"}}';}}});
 await probe(`jsonld-context-${hostname}`,()=>m.loadOntologyFromOntologyDocument(new StringDocumentSource(JSON.stringify({'@context':`https://${hostname}/context`,'@id':'urn:a','@type':'http://www.w3.org/2002/07/owl#Class'}),{format:F.JSON_LD}),new LC({remoteJsonLdContexts:true})).then(o=>({calls,count:o.getAxiomCount()})));
 results.push({id:`jsonld-context-${hostname}-calls`,calls});
}
let calls=0;
const m=OWLManager.createOWLOntologyManager({documentLoader:{load:async iri=>{calls++;const i=Number(iri.value.split('/').pop());return JSON.stringify({'@context': i<13?`https://context.example/${i+1}`:{x:'urn:x'}});}}});
await probe('jsonld-context-chain13',()=>m.loadOntologyFromOntologyDocument(new StringDocumentSource('{"@context":"https://context.example/0","@id":"urn:a","@type":"http://www.w3.org/2002/07/owl#Class"}',{format:F.JSON_LD}),new LC({remoteJsonLdContexts:true})).then(o=>o.getAxiomCount()));
results.push({id:'jsonld-context-chain13-calls',calls});
console.log(JSON.stringify({runtime:process.version,results},null,2));

