import java.util.*;
import org.semanticweb.owlapi.apibinding.OWLManager;
import org.semanticweb.owlapi.model.*;
import org.semanticweb.owlapi.io.*;
import org.semanticweb.owlapi.formats.*;
import org.eclipse.rdf4j.rio.*;

class ProbeAdmissionJava {
 interface Run {Object run() throws Exception;}
 static void probe(String name,Run fn) {try {System.out.println(name+"\tRETURN\t"+fn.run());}catch(Throwable e){System.out.println(name+"\tTHROW\t"+e.getClass().getName()+": "+e.getMessage().lines().findFirst().orElse(""));}}
 static Object load(String text,OWLDocumentFormat f) throws Exception{return OWLManager.createOWLOntologyManager().loadOntologyFromOntologyDocument(f==null?new StringDocumentSource(text):new StringDocumentSource(text,IRI.create("urn:research:document"),f,null)).getAxiomCount();}
 public static void main(String[] args)throws Exception{
  probe("sniff-leading9000-spaces",()->load(" ".repeat(9000)+"Ontology(<urn:research:sniff>)",null));
  probe("sniff-leading9000-spaces-explicit",()->load(" ".repeat(9000)+"Ontology(<urn:research:sniff>)",new FunctionalSyntaxDocumentFormat()));
  probe("xml-unused-external-entity",()->load("<!DOCTYPE Ontology [<!ENTITY unused SYSTEM \"https://example.invalid/no-network\">]><Ontology xmlns=\"http://www.w3.org/2002/07/owl#\" ontologyIRI=\"urn:research:xml\"/>",new OWLXMLDocumentFormat()));
  String nested="<Ontology xmlns=\"http://www.w3.org/2002/07/owl#\" ontologyIRI=\"urn:research:deepxml\"><Declaration><Class IRI=\"urn:research:A\"/></Declaration><SubClassOf><Class IRI=\"urn:research:A\"/>"+"<ObjectComplementOf>".repeat(110)+"<Class IRI=\"urn:research:A\"/>"+"</ObjectComplementOf>".repeat(110)+"</SubClassOf></Ontology>";
  probe("xml-complement-depth110",()->load(nested,new OWLXMLDocumentFormat()));
  probe("functional-literal1048577",()->load("Ontology(<urn:research:literal> Annotation(<urn:research:p> \""+"x".repeat(1048577)+"\"))",new FunctionalSyntaxDocumentFormat()));
  String trig="@prefix owl: <http://www.w3.org/2002/07/owl#> . <urn:g1> { <urn:A> a owl:Class . } <urn:g2> { <urn:B> a owl:Class . }";
  probe("trig-two-named-graphs",()->load(trig,new TrigDocumentFormat()));
  String turtle="@prefix owl: <http://www.w3.org/2002/07/owl#> . <urn:o> a owl:Ontology . <urn:x> <urn:p> \"value\" .";
  probe("turtle-undeclared-annotation-default",()->load(turtle,new TurtleDocumentFormat()));
  for(RDFFormat f:List.of(RDFFormat.RDFXML,RDFFormat.TURTLE,RDFFormat.JSONLD,RDFFormat.TRIG)){
   var parser=Rio.createParser(f);System.out.println("rio-parser\t"+f.getName()+"\t"+parser.getClass().getName());
   for(var setting:parser.getSupportedSettings()) if(setting.getKey().matches("(?i).*(limit|depth|large|xml|jsonld|timeout).*")) System.out.println("rio-setting\t"+f.getName()+"\t"+setting.getKey()+"\t"+setting.getDefaultValue());
  }
 }
}

