import java.util.*;
import java.util.stream.*;
import java.net.*;
import java.io.*;
import java.lang.reflect.*;
import org.semanticweb.owlapi.apibinding.OWLManager;
import org.semanticweb.owlapi.model.*;
import org.semanticweb.owlapi.io.*;
import org.semanticweb.owlapi.search.EntitySearcher;
import org.semanticweb.owlapi.modularity.locality.*;
class ProbeControlJava {
 static class Conn extends URLConnection {
  int calls=0; boolean fail;
  Conn(boolean fail)throws Exception{super(new URL("https://example.invalid/no-network"));this.fail=fail;}
  public void connect(){}
  public InputStream getInputStream()throws IOException{calls++;if(fail)throw new SocketTimeoutException("synthetic");return new ByteArrayInputStream(new byte[0]);}
 }
 public static void main(String[]args)throws Exception{
  Method method=DocumentSources.class.getDeclaredMethod("connectWithFiveRetries",IRI.class,OWLOntologyLoaderConfiguration.class,URLConnection.class,int.class,String.class);method.setAccessible(true);
  for(boolean fail:List.of(false,true))for(int retries:List.of(-1,0,1,2,5,6)){
   Conn conn=new Conn(fail);String outcome;
   try{Object result=method.invoke(null,IRI.create("https://example.invalid/no-network"),new OWLOntologyLoaderConfiguration().setRetriesToAttempt(retries),conn,20,null);outcome=result==null?"null":"stream";}catch(InvocationTargetException e){outcome=e.getCause().getClass().getSimpleName();}
   System.out.println("retries\tfail="+fail+"\tconfigured="+retries+"\tcalls="+conn.calls+"\tresult="+outcome);
  }
  var m=OWLManager.createOWLOntologyManager();var df=m.getOWLDataFactory();var a=df.getOWLClass(IRI.create("urn:A"));var b=df.getOWLClass(IRI.create("urn:B"));var ax=df.getOWLSubClassOfAxiom(a,b);var ont=m.createOntology(Set.of(ax));
  var extractor=new SyntacticLocalityModuleExtractor(LocalityClass.BOTTOM,Stream.of(ax));int[] calls={0};var module=extractor.extract(Stream.empty(),Optional.of(value->{calls[0]++;return true;}));System.out.println("locality-empty-seed\tfilterCalls="+calls[0]+"\tmodule="+module.count());
  int[] visits={0};var results=EntitySearcher.getSuperClasses(a,Stream.of(ont).peek(o->visits[0]++));System.out.println("search-before-consume\tvisits="+visits[0]);System.out.println("search-after-consume\tcount="+results.count()+"\tvisits="+visits[0]);
 }
}
